async (page) => {
  const checks=[],errors=[],requests=[],viewports=[];
  page.on('pageerror',error=>errors.push(String(error)));
  page.on('console',msg=>{if(msg.type()==='error')errors.push(msg.text());});
  page.on('request',req=>requests.push({url:req.url(),method:req.method()}));
  const check=(name,pass)=>{checks.push({name,pass:!!pass});if(!pass)throw Error(name);};
  const read=()=>page.evaluate(()=>({model:window.__dateDetailUxPrototype.snapshot(),history:window.__dateDetailUxPrototype.history(),view:window.__dateDetailUxPrototype.view()}));
  const open=async(id='sample-A')=>{await page.locator(`[data-task-id="${id}"]`).getByRole('button',{name:'날짜·시간',exact:true}).click();};
  const dialog=page.getByRole('dialog'),progress=dialog.locator('#progress-details'),connections=dialog.locator('#connection-details');
  const toggle=async details=>{await details.locator('summary').first().focus();await page.keyboard.press('Enter');};
  await page.reload(); await page.getByRole('button',{name:'예시 초기화',exact:true}).click();
  const initial=await read();await open();
  check('H01 schedule primary, disclosures closed, source exact',await dialog.getByRole('heading',{name:'날짜·시간',exact:true}).isVisible()&&!(await progress.evaluate(el=>el.open))&&!(await connections.evaluate(el=>el.open))&&(await dialog.locator('#task-origin').innerText()).includes('예시 A'));
  await toggle(progress);await dialog.getByLabel('누적 진행 (%)',{exact:true}).fill('37');
  check('H02 pending progress blocks origin',await dialog.getByRole('button',{name:'원문 열기',exact:true}).isDisabled());
  await toggle(progress);await toggle(progress);
  check('H03 keyboard fold preserves progress draft without mutation',await dialog.getByLabel('누적 진행 (%)',{exact:true}).inputValue()==='37'&&JSON.stringify((await read()).model)===JSON.stringify(initial.model));
  await page.keyboard.press('Escape');
  check('H04 Escape cancels draft with zero model/history writes',JSON.stringify((await read()).model)===JSON.stringify(initial.model)&&(await read()).history.undo===0);
  await open();await dialog.getByRole('button',{name:'날짜·시간 적용',exact:true}).click();
  check('H05 same schedule has no history mutation',(await read()).history.undo===0);
  await dialog.locator('#execution-time').fill('10:20');
  check('H06 inherited time-only change warns and blocks origin',(await dialog.innerText()).includes('시간만 바꿔도')&&await dialog.getByRole('button',{name:'원문 열기',exact:true}).isDisabled());
  await dialog.getByRole('button',{name:'날짜·시간 적용',exact:true}).click();
  let current=await read();check('H07 schedule retains identity/memo/peer and enables origin',current.model.tasks[0].time==='10:20'&&current.model.tasks[0].note===initial.model.tasks[0].note&&JSON.stringify(current.model.tasks[1])===JSON.stringify(initial.model.tasks[1])&&await dialog.getByRole('button',{name:'원문 열기',exact:true}).isEnabled());
  await dialog.getByRole('button',{name:'원문 열기',exact:true}).click();
  await page.waitForFunction(()=>document.activeElement?.id==='source-sample-A');
  check('H08 same source returns with exact focused identity',await page.evaluate(()=>document.activeElement?.id==='source-sample-A'));
  await page.getByRole('button',{name:'변경 되돌리기',exact:true}).click();check('H09 Undo restores entire original model',JSON.stringify((await read()).model)===JSON.stringify(initial.model));
  await page.getByRole('button',{name:'다시 실행',exact:true}).click();check('H10 Redo restores only successful schedule',(await read()).model.tasks[0].time==='10:20');
  await page.locator('.review-tools>summary').click();await page.getByLabel('다음 변경 적용에 실패 넣기',{exact:true}).check();await open();
  await dialog.getByLabel('실행 날짜',{exact:true}).fill('2026-10-08');const beforeFailure=await read();
  await dialog.getByRole('button',{name:'날짜·시간 적용',exact:true}).click();
  check('H11 rejection retains draft and last success with zero history change',await dialog.getByRole('alert').isVisible()&&await dialog.getByLabel('실행 날짜',{exact:true}).inputValue()==='2026-10-08'&&JSON.stringify((await read()).model)===JSON.stringify(beforeFailure.model)&&(await read()).history.undo===beforeFailure.history.undo);
  await dialog.getByRole('button',{name:'같은 입력으로 다시 시도',exact:true}).click();
  check('H12 retry succeeds, clears old error and preserves peer',(await read()).model.tasks[0].date==='2026-10-08'&&!(await dialog.getByRole('alert').isVisible())&&JSON.stringify((await read()).model.tasks[1])===JSON.stringify(initial.model.tasks[1]));
  await toggle(progress);await dialog.getByLabel('누적 진행 (%)',{exact:true}).fill('45');await dialog.getByRole('button',{name:'진행 기록',exact:true}).click();
  check('H13 progress success unblocks source and preserves date',await dialog.getByRole('button',{name:'원문 열기',exact:true}).isEnabled()&&(await read()).model.tasks[0].records.some(r=>r.percent===45)&&(await read()).model.tasks[0].date==='2026-10-08');
  await toggle(connections);await dialog.locator('#link-document').selectOption('doc-two');
  check('H14 reference keeps original owner/memo',(await read()).model.tasks[0].docId==='doc-one'&&(await read()).model.tasks[0].references.includes('doc-two')&&(await read()).model.tasks[0].note===initial.model.tasks[0].note);
  await dialog.getByRole('button',{name:'원문 열기',exact:true}).click();await page.getByRole('button',{name:'주간',exact:true}).click();await open();
  check('H15 period projects same source identity',(await read()).view.targetId==='sample-A');
  await dialog.getByRole('button',{name:'날짜 미정으로 이동',exact:true}).click();await page.keyboard.press('Escape');
  check('H16 removed period opener returns focus to active view',await page.evaluate(()=>document.activeElement?.getAttribute('data-view')==='week')&&(await read()).model.tasks[0].time==='10:20');
  await page.getByRole('button',{name:'예시 초기화',exact:true}).click();
  for(const [width,height] of [[390,844],[375,812],[844,390],[1024,768],[1440,900]]){
    await page.setViewportSize({width,height});await open();
    const initialScheduleVisible=await dialog.evaluate(el=>{const h=el.querySelector('.dialog-header').getBoundingClientRect(),s=el.querySelector('#schedule-title').getBoundingClientRect();return s.top>=h.bottom&&s.bottom<=innerHeight;});
    check(`HI${width}x${height} schedule initially readable`,initialScheduleVisible);
    await page.screenshot({path:`output/playwright/date-detail/prototype-initial-${width}x${height}.png`});
    const hit=async locator=>{await locator.scrollIntoViewIfNeeded();return locator.evaluate(el=>{const r=el.getBoundingClientRect(),h=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return r.width>=44&&r.height>=44&&r.x>=0&&r.y>=0&&r.right<=innerWidth&&r.bottom<=innerHeight&&!!h&&(h===el||el.contains(h));});};
    const applyHit=await hit(dialog.getByRole('button',{name:'날짜·시간 적용',exact:true}));const closeHit=await hit(dialog.getByRole('button',{name:'닫기',exact:true}));
    let overflow=await page.evaluate(()=>Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth),dialogOverflow=await dialog.evaluate(el=>el.scrollWidth-el.clientWidth);
    check(`HC${width}x${height} primary hit/overflow`,applyHit&&closeHit&&overflow<=1&&dialogOverflow<=1);
    await page.screenshot({path:`output/playwright/date-detail/prototype-primary-${width}x${height}.png`});
    await toggle(progress);await toggle(connections);const recordHit=await hit(dialog.getByRole('button',{name:'진행 기록',exact:true}));const originHit=await hit(dialog.getByRole('button',{name:'원문 열기',exact:true}));const expandedCloseHit=await hit(dialog.getByRole('button',{name:'닫기',exact:true}));
    dialogOverflow=await dialog.evaluate(el=>el.scrollWidth-el.clientWidth);
    check(`HE${width}x${height} expanded hit/overflow`,recordHit&&originHit&&expandedCloseHit&&dialogOverflow<=1);
    await page.screenshot({path:`output/playwright/date-detail/prototype-expanded-${width}x${height}.png`});await page.keyboard.press('Escape');viewports.push({width,height,initialScheduleVisible,overflow,dialogOverflow,applyHit,closeHit,recordHit,originHit,expandedCloseHit});
  }
  check('H17 no browser error or external request',errors.length===0&&requests.every(r=>r.method==='GET'&&r.url==='http://127.0.0.1:3116/date-detail.html'));
  return {schema:'flowme-date-detail-prototype-qa/1',checks,passed:checks.filter(c=>c.pass).length,failed:checks.filter(c=>!c.pass).length,viewports,errors,requests,device:false,observedUsers:0};
}
